const body = $input.first().json.body;
if (!body || !body.data || !Array.isArray(body.data.fields)) {
  throw new Error('Structure Tally invalide');
}
const fields = body.data.fields;

function resolve(field) {
  if (!field) return 'Non renseigné';
  const v = field.value;
  if (v === null || v === undefined || v === '' || v === false) return 'Non renseigné';
  if (typeof v === 'boolean') return v ? 'Oui' : 'Non';
  if (Array.isArray(v) && field.options && field.options.length > 0) {
    const texts = v.map(uuid => {
      const opt = field.options.find(o => o.id === uuid);
      return opt ? opt.text : uuid;
    }).filter(Boolean);
    return texts.length > 0 ? texts.join(', ') : 'Non renseigné';
  }
  if (Array.isArray(v)) return v.join(', ') || 'Non renseigné';
  return String(v).trim() || 'Non renseigné';
}

function getByLabel(...labels) {
  const normalizedLabels = labels.map(l => l.toLowerCase().trim());
  // Filtrer pour ne pas prendre les booléens (étonnamment n8n renvoie 'Oui' pour l'email sometimes)
  let f = fields.find(field => {
     if (!field.label) return false;
     const fl = field.label.toLowerCase().trim();
     return normalizedLabels.includes(fl) && typeof field.value !== 'boolean';
  });
  if (!f) {
    f = fields.find(field => {
      if (!field.label) return false;
      const fl = field.label.toLowerCase();
      return normalizedLabels.some(nl => fl.includes(nl)) && typeof field.value !== 'boolean';
    });
  }
  return f ? resolve(f) : 'Non renseigné';
}

const langPayload = body.data.formLanguage || body.data.lang || '';
const langueRaw = getByLabel('Langue', 'Language');
const isEnglish = langPayload.toLowerCase().includes('en') || langueRaw.toLowerCase().includes('en') || langueRaw.toLowerCase().includes('english');
const langue = isEnglish ? 'en' : 'fr';

const rawId = body.data.respondentId || '';
const respondentId = rawId.trim().split(/[\s🇺🇸🇬🇧🇫🇷]/)[0] || rawId;

return [{
  json: {
    respondentId,
    submissionId: body.data.submissionId || '',
    nom:        getByLabel('Prénom et Nom', 'Nom complet', 'Nom', 'Name'),
    email:      getByLabel('Email professionnel', 'Email', 'Adresse email'),
    site:       getByLabel('Site e-commerce (URL)', 'Site web', 'Website'),
    plateforme: getByLabel('Plateforme utilisée', 'Platform'),
    ca:         getByLabel('Taille de la boutique', 'CA mensuel', 'Revenue'),
    probleme:   getByLabel('Problème principal', 'Main problem'),
    objectif:   getByLabel('Objectif business principal', 'Goal'),
    budget:     getByLabel('Budget estimé', 'Budget'),
    urgence:    getByLabel('Urgence', 'Timeline'),
    autoExist:  getByLabel('Automatisations déjà en place', 'Existing tools'),
    source:     getByLabel('Source de découverte', 'Source'),
    langue
  }
}];

const rows = $input.all().map(i => i.json).filter(r => r && r.email && String(r.email).includes('@'));
const lead = $('Extract Tally Data').first().json;
const alreadyDone = rows.length > 0;
return [{ json: { ...lead, alreadyDone } }];

